    let result = [];
    let current_group = [];
    let open_braces = 0;
    let close_braces = 0;
    let i = 0;
    while(i < paren_string.length){
        let char = paren_string[i];
        if(char === '('){
            open_braces++;
            current_group.push(char);
        }
        else if(char === ')'){
            close_braces++;
            current_group.push(char);
            if(open_braces === close_braces){
                result.push(current_group.join(''));
                current_group = [];
                open_braces = 0;
                close_braces = 0;
            }
        }
        i++;
    }
    return result;
}

