    let sum = 0;
    let sum_sq = 0;
    let mean = 0;
    for(let i = 0; i < numbers.length; i++){
        sum += numbers[i];
        sum_sq += numbers[i] * numbers[i];
    }
    mean = sum / numbers.length;
    let sum_sq_diff = 0;
    for(let i = 0; i < numbers.length; i++){
        sum_sq_diff += Math.pow(numbers[i] - mean, 2);
    }
    return Math.sqrt(sum_sq_diff / numbers.length);
}
